"""CuP lookup tables generated by pristine WRF's REAL KF_LUTAB.

The generation receipt is proofs/v040/cuplus/KFCUP_TABLES.json. This asset
retains the original REAL recurrence and secant termination, including the
ALU pressure/iteration rounding absent from the historical KF-eta tables.
Host NumPy data only: no JAX arrays or tracers are cached at import time.
"""
from pathlib import Path
import numpy as np

KFNT, KFNP = 250, 220
with np.load(Path(__file__).with_name('data') / 'kfcup_real_tables.npz', allow_pickle=False) as _asset:
    TTAB_R4, QSTAB_R4, THE0K_R4, ALU = (np.array(_asset[key], dtype=np.float32)
                                      for key in ('TTAB', 'QSTAB', 'THE0K', 'ALU'))
    RDPR, RDTHK, PLUTOP = (np.float32(_asset[key]) for key in ('RDPR', 'RDTHK', 'PLUTOP'))
for _table in (TTAB_R4, QSTAB_R4, THE0K_R4, ALU):
    _table.setflags(write=False)
del _table, _asset
